const ZONE = 'Africa/Abidjan';
const today = $now.setZone(ZONE).toFormat('yyyy-MM-dd');

// Les deux canaux ne parlent pas la meme langue de balisage.
// Telegram lit du HTML quand on lui demande d'analyser : un produit nomme
// « Riz & sauce » ferait echouer l'envoi entier. WhatsApp, lui, ne peut pas
// echouer — le risque n'y est que cosmetique.
const ech = (v) => String(v ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .trim();
const net = (v) => String(v ?? '').replace(/[*_~`]/g, '').trim();

// Une seule alerte par produit et par niveau, remise a zero chaque jour.
// La cle inclut la boutique : sans cela, deux marchands vendant le meme
// produit se masqueraient mutuellement leurs alertes.
//
// On LIT le registre ici, on ne l'ECRIT PAS. Le marquage appartient au noeud
// « Marquer envoyees », apres les deux envois : marquer des ce point revenait
// a oublier pour la journee entiere une alerte que personne n'avait recue.
const sd = $getWorkflowStaticData('global');
if (sd.alertesDate !== today) { sd.alertes = {}; sd.alertesDate = today; }
if (!sd.alertes) sd.alertes = {};

// L'API a deja ecarte les produits au-dessus du seuil et calcule le niveau.
const lignes = ($input.first().json.lignes) || [];
const alertes = [];
for (const r of lignes) {
  if (!r || !r.produit) continue;
  const cle = `${r.slug}:${r.produit}:${r.niveau}`;
  if (sd.alertes[cle]) continue;
  alertes.push({ ...r, cle });
}

if (!alertes.length) return [];

const parBoutique = new Map();
for (const a of alertes) {
  const cle = a.boutique_nom || 'Boutique inconnue';
  if (!parBoutique.has(cle)) parBoutique.set(cle, []);
  parBoutique.get(cle).push(a);
}

let tg = `🚨 <b>ALERTE STOCK</b>\n`;
let wa = `🚨 *ALERTE STOCK*\n`;

for (const [boutique, liste] of parBoutique) {
  tg += `\n━━━━━━━━\n🏪 <b>${ech(boutique)}</b>\n`;
  wa += `\n━━━━━━━━\n🏪 *${net(boutique)}*\n`;
  for (const a of liste) {
    const pastille = a.niveau === 'critique' ? '🔴' : '🟠';
    const reste = `${a.restant} restant(s) (seuil : ${a.seuil})`;
    tg += `${pastille} <b>${ech(a.produit)}</b> : ${ech(reste)}\n`;
    wa += `${pastille} *${net(a.produit)}* : ${reste}\n`;
  }
}

const pied = `\n💡 Pensez a reapprovisionner avant la rupture.\n━━━━━━━━\nGenere automatiquement par DjiguiFlow 🤖`;
tg += pied;
wa += pied;

return [{ json: {
  message_telegram: tg,
  message_whatsapp: wa,
  cles: alertes.map(a => a.cle),
} }];

// Seul noeud a ecrire le registre anti-doublon — et seulement si l alerte est
// reellement partie.
//
// Il s executait auparavant quoi qu il arrive : `Envoyer reponse client`
// avalait ses echecs et ne tombait jamais en erreur, si bien que la garde
// « le workflow s arrete avant » n a jamais rien garde. On lit donc les deux
// verdicts.
//
// Ce noeud ne doit pas lever non plus : n8n n enregistre la memoire statique
// qu au terme d une execution reussie, et lever ici jetterait le marquage
// qu on vient d ecrire.
const ZONE = 'Africa/Abidjan';
const today = $now.setZone(ZONE).toFormat('yyyy-MM-dd');

const cles = $('Calcul Stock').first().json.cles || [];

const sd = $getWorkflowStaticData('global');
if (sd.alertesDate !== today) { sd.alertes = {}; sd.alertesDate = today; }
if (!sd.alertes) sd.alertes = {};

// Les deux noeuds d envoi tolerent leur propre echec, sans quoi le premier
// emporterait le second en tombant. Un noeud en echec rend un item d erreur,
// donc `ok` absent.
const verdict = (nom) => {
  try { return $(nom).first().json || {}; } catch (e) { return {}; }
};
const partis = [
  verdict('Alerte WhatsApp marchand').ok === true ? 'whatsapp' : null,
  verdict('Alerte Telegram marchand').ok === true ? 'telegram' : null,
].filter(Boolean);

// Aucun canal n a abouti : ne rien marquer, l alerte repartira au prochain
// passage. L exploitant, lui, a deja ete prevenu par `Envoyer reponse client`.
// Mieux vaut une alerte en double qu une rupture de stock que personne n a vue.
if (!partis.length) {
  return [{ json: { marquees: 0, partis, note: 'aucun canal aboutti' } }];
}

for (const cle of cles) sd.alertes[cle] = true;

return [{ json: { marquees: cles.length, partis } }];

